 * Parsing and mapping logic from pnpm lockfile `read` function
 */
export function parseAndNormalizePnpmLockfile(content: string): Lockfile {
  const { load, loadAll } = require('@zkochan/js-yaml');

  // Newer pnpm versions can emit a multi-document YAML lockfile where the
  // first document holds package-manager dependency metadata (e.g. the
  // `packageManagerDependencies` entry describing pnpm itself) and a
  // subsequent document holds the actual workspace dependency graph. Only the
  // workspace dependency document should be used to build the graph.
  if (isMultiDocumentLockfile(content)) {
    const documents: unknown[] = [];
    loadAll(content, (doc: unknown) => documents.push(doc));
    const workspaceDocument = selectWorkspaceDependencyDocument(documents);
    return convertToLockfileObject(workspaceDocument);
  }

  return convertToLockfileObject(load(content));
}

/**
 * Detects whether the lockfile content is in multi-document YAML format, i.e.
 * it contains more than one document separated by YAML document delimiters.
 */
function isMultiDocumentLockfile(content: string): boolean {
  // A YAML document separator is a line that consists solely of `---`
  // (optionally followed by trailing whitespace or a comment). Content that
  // merely starts with a leading `---` marker is still a single document, so
  // we only treat the file as multi-document when a separator appears after
  // the first document has started.
  const lines = content.split(/\r?\n/);
  let seenContent = false;
  for (const line of lines) {
    if (line.trim() === '---' || /^---\s/.test(line)) {
      if (seenContent) {
        return true;
      }
      // A leading document marker before any content just opens the first
      // document; keep scanning for a real separator.
      continue;
    }
    if (line.trim() !== '' && !line.trim().startsWith('#')) {
      seenContent = true;
    }
  }
  return false;
}

/**
 * Given the documents of a multi-document lockfile, returns the one that
 * describes the workspace dependency graph (the main lockfile document),
 * ignoring the package-manager metadata document.
 */
function selectWorkspaceDependencyDocument(documents: unknown[]): any {
  const candidates = documents.filter(
    (doc): doc is Record<string, unknown> =>
      doc != null && typeof doc === 'object'
  );

  // Prefer the document that actually describes the dependency graph.
  const lockfileDocument = candidates.find(
    (doc) =>
      'importers' in doc ||
      'packages' in doc ||
      'snapshots' in doc ||
      'lockfileVersion' in doc
  );
  if (lockfileDocument) {
    return lockfileDocument;
  }

  // Otherwise fall back to the first document that is not the package-manager
  // metadata document.
  const nonMetadataDocument = candidates.find(
    (doc) => !('packageManagerDependencies' in doc)
  );
  return nonMetadataDocument ?? candidates[candidates.length - 1];
